<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Client\Domain\ApiKeyData;
use Civi\Lughauth\Features\OAuth\Client\Domain\DynamicClientData;
use Civi\Lughauth\Features\OAuth\Client\Domain\Exception\DynamicClientException;

final class ClientDomainUnitTest extends TestCase
{
    // --- ClientData ---

    public function test_client_data_stores_required_fields(): void
    {
        $c = new ClientData('my-client', ['authorization_code'], true);
        $this->assertSame('my-client', $c->id);
        $this->assertSame(['authorization_code'], $c->grants);
        $this->assertTrue($c->secretLogin);
        $this->assertSame([], $c->allowedScopesM2m);
        $this->assertSame(3600, $c->m2mTokenTtlSeconds);
    }

    public function test_client_data_stores_optional_fields(): void
    {
        $c = new ClientData('c', ['cc'], false, ['api:r'], 7200, 'RS256', 'https://jwks.uri', '{"keys":[]}');
        $this->assertSame(['api:r'], $c->allowedScopesM2m);
        $this->assertSame(7200, $c->m2mTokenTtlSeconds);
        $this->assertSame('RS256', $c->requestObjectSigningAlg);
        $this->assertSame('https://jwks.uri', $c->jwksUri);
        $this->assertSame('{"keys":[]}', $c->jwksJson);
    }

    // --- ApiKeyData ---

    public function test_api_key_data_stores_fields(): void
    {
        $k = new ApiKeyData('key-id', ['api:read', 'api:write']);
        $this->assertSame('key-id', $k->id);
        $this->assertSame(['api:read', 'api:write'], $k->scopes);
    }

    // --- DynamicClientData ---

    public function test_dynamic_client_data_stores_all_fields(): void
    {
        $d = new DynamicClientData(
            clientId: 'dyn-1',
            redirectUris: ['https://app/cb'],
            grantTypes: ['authorization_code'],
            responseTypes: ['code'],
            scope: 'openid',
            tokenEndpointAuthMethod: 'client_secret_basic',
            clientName: 'My App',
            logoUri: null,
            clientUri: null,
            policyUri: null,
            tosUri: null,
            backchannelLogoutUri: null,
            frontchannelLogoutUri: null,
            clientIdIssuedAt: 1700000000,
            registrationClientUri: 'https://auth/register/dyn-1',
        );

        $this->assertSame('dyn-1', $d->clientId);
        $this->assertSame(['https://app/cb'], $d->redirectUris);
        $this->assertSame('openid', $d->scope);
        $this->assertSame(1700000000, $d->clientIdIssuedAt);
    }

    // --- DynamicClientException ---

    public function test_invalid_redirect_uri(): void
    {
        $ex = DynamicClientException::invalidRedirectUri('http://bad');
        $this->assertSame('invalid_redirect_uri', $ex->error());
        $this->assertSame(400, $ex->statusCode());
        $this->assertStringContainsString('http://bad', $ex->getMessage());
    }

    public function test_invalid_client_metadata(): void
    {
        $ex = DynamicClientException::invalidClientMetadata('logo_uri invalid');
        $this->assertSame('invalid_client_metadata', $ex->error());
    }

    public function test_registration_not_allowed(): void
    {
        $ex = DynamicClientException::registrationNotAllowed();
        $this->assertSame('access_denied', $ex->error());
        $this->assertSame(403, $ex->statusCode());
    }

    public function test_invalid_token(): void
    {
        $ex = DynamicClientException::invalidToken();
        $this->assertSame('invalid_token', $ex->error());
        $this->assertSame(401, $ex->statusCode());
    }

    public function test_not_found(): void
    {
        $ex = DynamicClientException::notFound();
        $this->assertSame('invalid_client_id', $ex->error());
        $this->assertSame(404, $ex->statusCode());
    }

    public function test_token_required(): void
    {
        $ex = DynamicClientException::tokenRequired();
        $this->assertSame('access_denied', $ex->error());
        $this->assertSame(401, $ex->statusCode());
    }
}
